    intro: 'GLM-5.2, publié le 13 juin 2026 par Z.ai (anciennement Zhipu AI), était à son lancement le modèle de langage open-weights le mieux classé sur l\'Artificial Analysis Intelligence Index indépendant — n°1 des modèles ouverts et 4e au classement général. Depuis août 2026, Kimi K3 de Moonshot AI (publié le 27 juillet 2026) occupe la première place des poids ouverts, GLM-5.2 se classant désormais 2e. GLM-5.2 continue de dépasser GPT-5.5 sur les benchmarks de code mais reste derrière les modèles de frontière fermée actuels. Cet article distingue les résultats indépendants des affirmations de Z.ai, suit GLM-5.2 face à Kimi K3 et au plus récent GLM-5.3 de Z.ai, et explique pourquoi un modèle ouvert d\'environ 744B de paramètres ne s\'exécute toujours pas chez vous.',
    metaDescription: 'GLM-5.2 dominait l\'open-weights à son lancement ; Kimi K3 l\'a dépassé en juillet 2026. GLM-5.2 est désormais n°2, bat GPT-5.5 sur le code — ses ~744B ne tournent toujours pas chez vous.',
    twitterDescription: 'Mise à jour : Kimi K3 a dépassé GLM-5.2 comme meilleur LLM open-weights en juillet 2026. GLM-5.2 est désormais n°2, bat toujours GPT-5.5 sur le code — et ses ~744B ne tournent toujours pas sur votre ordinateur portable.',
