          '**Nº 2 em pesos abertos, era o 1º no lançamento.** O GLM-5.2 pontuou 51 no Artificial Analysis Intelligence Index v4.1 no lançamento, em junho de 2026 — o melhor modelo de pesos abertos na época. Desde agosto de 2026, o **Kimi K3** da Moonshot AI (57, lançado em 27 de julho de 2026) ocupa o 1º lugar em pesos abertos; o GLM-5.2 (agora com cerca de 52,6 no índice v4.1.1 atualizado) é o 2º, ainda à frente de MiniMax-M3 e DeepSeek V4 Pro (44 cada).',
