            a: 'Não — em agosto de 2026, o Kimi K3 da Moonshot AI (lançado em 27 de julho de 2026) ocupa o 1º lugar no Artificial Analysis Intelligence Index com 57 pontos, à frente dos cerca de 52,6 do GLM-5.2. O GLM-5.2 era o 1º em pesos abertos no lançamento, em junho de 2026 (51 pontos), mas agora é o 2º, ainda à frente de MiniMax-M3 e DeepSeek V4 Pro (ambos com 44).',
