    seoTitle: 'GLM-5.2：开源权重 LLM 现状 2026',
    intro: 'GLM-5.2 由 Z.ai（前身为 Zhipu AI）于 2026 年 6 月 13 日发布，在发布时是独立的 Artificial Analysis Intelligence Index 上得分最高的开源权重大语言模型——在开源模型中排名第一，整体排名第四。截至 2026 年 8 月，Moonshot AI 的 Kimi K3（2026 年 7 月 27 日发布）已夺得开源权重第一的位置，GLM-5.2 现排名第二。GLM-5.2 在编程基准测试上仍领先 GPT-5.5，但落后于当前的闭源前沿模型。本文将独立测评结果与 Z.ai 自报数据区分开来，追踪 GLM-5.2 相对于 Kimi K3 及 Z.ai 更新的 GLM-5.3 的表现，并解释为何一个约 744B 参数的开源模型仍无法在家本地运行。',
