    leadAnswerBlock: '**GLM-5.2 由 Z.ai（前身为 Zhipu AI）于 2026 年 6 月 13 日发布，在发布时是 Artificial Analysis Intelligence Index 上得分最高的开源权重 LLM。截至 2026 年 8 月，Moonshot AI 的 Kimi K3（2026 年 7 月 27 日发布）已占据开源权重第一的位置，GLM-5.2 现排名第二。GLM-5.2 仍领先于 GPT-5.5，但未击败闭源前沿模型。而且在约 744B 参数下，"开源且可自托管"仍不等于"能在你的笔记本上运行"。**',
